const $=s=>document.querySelector(s);let page='home',watched=new Set();
try{const stored=JSON.parse(localStorage.getItem('assemble-watched-v1')||'null');if(Array.isArray(stored))watched=new Set(stored.filter(id=>MOVIES.some(m=>m.id===id&&!m.upcoming)));else{const legacy=JSON.parse(localStorage.getItem('marvel-atlas-watched')||'[]');const ids={15:'homecoming',22:'farfromhome',26:'nowayhome'};watched=new Set((Array.isArray(legacy)?legacy:[]).map(id=>ids[id]).filter(Boolean))}}catch{}
function showPage(id,focus=false){if(!['home','guide','weblab'].includes(id))id='home';page=id;document.querySelectorAll('[role=tabpanel]').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('[data-page]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.page===id));b.tabIndex=b.dataset.page===id?0:-1;if(focus&&b.dataset.page===id)b.focus()});if(location.hash!=='#'+id)history.replaceState(null,'','#'+id);window.scrollTo({top:0,behavior:'instant'});window.dispatchEvent(new CustomEvent('assemble-page',{detail:id}))}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>showPage(b.dataset.go,true));document.querySelector('nav').addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[data-page]')];let i=tabs.indexOf(document.activeElement);if(e.key==='ArrowRight')i=(i+1)%tabs.length;else if(e.key==='ArrowLeft')i=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();showPage(tabs[i].dataset.page,true)});window.addEventListener('hashchange',()=>showPage(location.hash.slice(1)));
function movieCard(m){return `<article class="movie-card"><div class="poster-frame"><img src="${m.image}" alt="${m.title} theatrical poster" loading="lazy" width="600" height="900"></div><div class="movie-meta"><span>${m.year}</span><span>${m.series}</span></div><h3>${m.title}</h3><p>${m.summary}</p><button class="watched" data-watch="${m.id}" aria-label="${watched.has(m.id)?'Mark unwatched':'Mark watched'}: ${m.title}" aria-pressed="${watched.has(m.id)}"><span aria-hidden="true">${watched.has(m.id)?'✓':'○'}</span>${watched.has(m.id)?'Watched':'Mark watched'}</button></article>`}
function renderMovies(){const q=$('#search').value.toLowerCase().trim(),series=$('#series').value;const matches=MOVIES.filter(m=>(series==='all'||m.era===series)&&(m.title+' '+m.series).toLowerCase().includes(q));const released=matches.filter(m=>!m.upcoming).sort((a,b)=>a.date.localeCompare(b.date)),upcoming=matches.filter(m=>m.upcoming);$('#movie-list').innerHTML=released.map(movieCard).join('');$('#empty').hidden=matches.length>0;$('#movie-list').hidden=released.length===0;$('#upcoming-section').hidden=upcoming.length===0;$('#upcoming-list').innerHTML=upcoming.map(m=>`<article class="upcoming-card"><span class="upcoming-tag">UPCOMING · ${m.series.toUpperCase()}</span><h3>${m.title}</h3><span class="release-date">${new Date(m.date+'T12:00:00Z').toLocaleDateString('en-US',{timeZone:'UTC',month:'long',day:'numeric',year:'numeric'})}</span><p>${m.summary}</p><a href="${m.source}" target="_blank" rel="noopener noreferrer">Official film updates ↗</a></article>`).join('');const total=MOVIES.filter(m=>!m.upcoming),done=total.filter(m=>watched.has(m.id)).length;$('#watch-progress').textContent=`${done} / ${total.length} released films watched`;$('#collection-note').textContent='11 released films. Four Spider-Man series. Choose an actor or the animated films to follow one story.';document.querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>{const id=b.dataset.watch;watched.has(id)?watched.delete(id):watched.add(id);try{localStorage.setItem('assemble-watched-v1',JSON.stringify([...watched]))}catch{}renderMovies()})}
$('#search').oninput=renderMovies;$('#series').onchange=renderMovies;$('#reset-filters').onclick=()=>{$('#search').value='';$('#series').value='all';renderMovies()};renderMovies();showPage(location.hash.slice(1)||'home');
